    contrib:
      "Khadija bint Khuwaylid was the wealthiest businesswoman in pre-Islamic Arabia — a title she had earned entirely through her own commercial skill in a society that had no framework for female economic independence. She had been widowed twice before the Prophet ﷺ. She was 40 years old, he was 25, when she proposed marriage to him directly — reversing the social convention of the era completely. She had employed him to lead her trade caravans to Syria and sent her servant Nafisa to sound out whether he would accept. He did. Their marriage lasted 25 years. He never took another wife while she lived — something unparalleled among men of his social standing in Arabia. She was the first human being to hear the words of revelation. She was the first to believe — immediately, without asking for a sign or time to reflect. Her response to him trembling in the cave after the first revelation is Islam's earliest pastoral care: 'By Allah, He will never disgrace you. You maintain family ties, carry the burdens of the weak, give to those who have nothing, honor guests, and help people in times of genuine need.' Then she took him to her cousin Waraqa ibn Nawfal — a Christian scholar — who confirmed the revelation was the same that had come to Moses. She supported the growing Muslim community financially for 25 years — every hostile boycott, every financial pressure from the Quraysh, every refugee in need was met by her wealth. When she died in 619 CE — the Year of Sorrow — the Prophet ﷺ buried her himself and descended into her grave. He said: 'She believed when people disbelieved, she gave her wealth when people withheld, and she bore children for me when others did not.' He kept speaking of her with love for the rest of his life. When Aisha later expressed jealousy of his memory of Khadija, he said: 'Allah has not given me better than her.'",
