      "Juwayriyya bint al-Harith transformed the lives of an entire tribe through a single marriage. After the Battle of al-Muraysi (Banu Mustaliq), she came to the Prophet ﷺ to ask for help buying her freedom from the companion in whose share she had fallen as a captive. The Prophet ﷺ said: 'Shall I pay your ransom and marry you?' She agreed. The moment the news spread through the camp that the Prophet ﷺ had married the chief's daughter, every companion released their Banu Mustaliq captives voluntarily — calculating that their prisoners were now the in-laws of the Prophet ﷺ. Approximately 100 families were freed simultaneously. Aisha said: 'I know of no woman who was a greater blessing to her people than Juwayriyya.' Her father al-Harith — who had hidden his finest camels before the battle — came to ransom his daughter. As he was going to do so, he stopped outside Medina, looked at two of the camels, thought: 'The Prophet of Allah should not be deprived of these,' and left them there as sadaqa before entering. He then converted to Islam before seeing his daughter. She narrated 7 hadiths. She died in 673 CE aged approximately 65, the last of the Mothers of the Believers to die after Umm Salama. Her legacy is entirely in the 100 families freed on the day of her marriage.",
