      "Ubadah ibn al-Samit al-Khazraji was one of the 12 Naqibs — tribal guarantors — of the Second Aqabah Pledge, which established Islam's political foundation in Medina. His pledge was among the first to bind the Ansar to the Prophet ﷺ in a formal political compact. He fought at Badr and every subsequent major battle. Umar ibn al-Khattab sent him to teach Islam in Palestine after the conquest — making him Islam's first official teacher in the Levant. His teaching methodology was systematic: he would gather people, explain the five pillars, then move through theology, ethics, and jurisprudence. He settled in Palestine for the rest of his life. The Quranic verse that changed Islamic commercial law — prohibiting usury (riba) — was transmitted primarily through his narration of the relevant hadiths. He narrated 181 hadiths total. His most famous narration is the comprehensive hadith on the Pledge of Aqabah: 'We pledged to the Prophet ﷺ to listen and obey in ease and hardship, willingly and reluctantly, and to give precedence to our affairs over those of others, and not to dispute authority with its people.' He died in Palestine approximately 34 AH. His tomb in Ascalon (Ashkelon) was venerated for centuries.",
