    contrib:
      "Suhayl ibn Amr was the Quraysh's finest orator and chief negotiator — the man Abu Sufyan specifically sent to Hudaybiyyah to negotiate against the Prophet ﷺ. He refused, with formal stubbornness, to allow the treaty text to read 'Muhammad, Messenger of Allah' — insisting on just 'Muhammad ibn Abdullah,' saying: 'If we acknowledged his prophethood, there would be no dispute.' He objected to the Arabic word 'Bismillah al-Rahman al-Rahim' in the preamble — forcing its replacement. He insisted on a clause requiring the return of Muslims who escaped Mecca to Medina. He negotiated from strength and got nearly everything his side demanded. The companions were furious at the terms. The Prophet ﷺ accepted. When Mecca was conquered and Suhayl's fate was uncertain — Umar ibn al-Khattab suggested his tongue be removed for all the speeches he had made against Islam — the Prophet ﷺ said: 'Leave him, Umar. Perhaps that same tongue will one day say something that will please you.' It did: when the Prophet ﷺ died and Mecca wavered, Suhayl stood before the Meccans and gave a speech confirming Islam, shaming those who considered apostasy, and pledging his own continued commitment. Umar wept when he heard it. He later fought at Yarmouk and died in the Amwas plague 639 CE — his final years spent entirely in the service of the religion he had spent two decades opposing.",
