      "Umm Habiba Ramlah bint Abi Sufyan underwent the most isolated and painful personal exile of any companion. She had migrated to Abyssinia with her husband Ubaydullah ibn Jahsh — both converts seeking safety. In Abyssinia, Ubaydullah converted to Christianity. He pressured her to convert with him. She refused absolutely. He died there a Christian. She was now a Muslim widow in a foreign country, cut off from her father Abu Sufyan (still a Qurayshi enemy of Islam at that time), with no support network, and no prospect of return. The Prophet ﷺ sent his envoy Amr ibn Umayya to King Negus with a proposal of marriage for her — delivered and accepted while she remained in Abyssinia. The Negus himself gave her mahr from his own treasury and hosted the wedding feast in Abyssinia, with the Prophet ﷺ absent. She returned to Medina already married. When her father Abu Sufyan later visited the Prophet's ﷺ house (before his conversion), he moved to sit on the Prophet's ﷺ bed and she immediately rolled it up: 'You are a polytheist and this is the bed of the Messenger of Allah.' Abu Sufyan was reportedly shaken — his own daughter had chosen her faith over her father, in his face, without hesitation. She narrated 65 hadiths and died approximately 44 AH. Her entire life was defined by the firmness she showed in Abyssinia — a firmness that never wavered.",
