    contrib:
      "Khawla bint Tha'laba was the woman whose personal dispute with her husband reached Allah directly. Her husband Aws ibn al-Samit had performed dhihar — an ancient Arabian practice declaring his wife 'like his mother's back,' which in pre-Islamic custom constituted an irrevocable divorce but left the woman in legal limbo (neither wife nor free). She came to the Prophet ﷺ and pleaded her case — she had children and an elderly husband who needed care and she could not simply be abandoned. The Prophet ﷺ initially said he had no ruling on it. She refused to accept that answer. Aisha, in the next room, said she could not hear all of Khawla's words — but Allah heard every word, from above seven heavens. The revelation of Surah al-Mujadila (58:1-4) came: 'Allah has heard the statement of the woman who pleads with you concerning her husband and carries her complaint to Allah — and Allah hears the dialogue between you. Verily Allah is All-Hearing, All-Seeing.' The entire surah is named al-Mujadila — 'The Pleading Woman' — after Khawla. Dhihar was forbidden and a specific expiation was legislated. One woman's refusal to accept injustice produced a permanent protection in Islamic law for all women in similar situations. She narrated 0 traditional hadiths. Her entire legacy is the surah named for her.",
