      "Shaddad ibn Aws al-Khazraji was the nephew of Hassan ibn Thabit (rank #63) and one of the companions who settled in Palestine after its conquest, where he became a foundational figure of the Jerusalem scholarly tradition. He was known for extreme weeping in prayer — a companion once found him alone at night, trembling, saying: 'O Allah, the Fire has taken away my sleep.' He narrated 50 hadiths. His most famous narration is the Sayyid al-Istighfar — the Master Supplication for Forgiveness — which the Prophet ﷺ taught him directly: 'Allahumma anta Rabbi, la ilaha illa anta, khalaqtani wa ana abduka...' The Prophet ﷺ said: 'Whoever says this with certainty in the morning and dies before evening enters paradise, and whoever says it with certainty in the evening and dies before morning enters paradise.' This du'a is among the most recited by Muslims globally every morning and evening. He also transmitted the hadith about the prohibition of mutilation in war, the treatment of the dead with dignity, and the rules of engagement — foundational texts of Islamic laws of war. He died in Palestine approximately 58 AH. His grave in the Bab al-Rahma cemetery in Jerusalem was known for centuries. He had approximately 300 students in Palestine alone.",
