    contrib:
      "A poet and warrior who fought heroically at Badr and Uhud. Missed Tabuk — unlike the hypocrites, he had no excuse and he knew it. When he came to the Prophet ﷺ and told the truth instead of lying, the Prophet ﷺ's face turned away and the boycott began. For 50 days, the entire community of Medina — thousands of people — refused to speak to him. Friends passed him in the street without acknowledgment. Even his wife was separated from him. The psychological torture was total. His two companions in this trial were Murarah ibn al-Rabi and Hilal ibn Umayyah. Then Quran 9:118 was revealed: 'And upon the three who were left behind — until the earth became straitened for them despite its vastness, and their own souls became straitened for them, and they were certain that there is no refuge from Allah except to Him.' The boycott ended and Ka'b said: 'Never in my life was I more blessed.' His account of these 50 days, preserved in Sahih al-Bukhari, is one of the most psychologically and spiritually detailed personal testimonies in all of Islamic literature.",
