    contrib:
      "Tufayl ibn Amr al-Dawsi was a chief of the Daws tribe and one of Yemen's most celebrated poets — with a reputation so powerful that the Quraysh, when he visited Mecca, stuffed cotton in their ears (according to one narration) or surrounded and warned him against listening to Muhammad (according to others). The precaution failed: he heard the Prophet ﷺ recite Quran while circumambulating the Ka'bah and said to himself: 'By my mother and father, I am a poet — I know good speech from bad. What prevents me from hearing what this man says?' He heard. He converted that night. He returned to Yemen and converted his father and wife immediately. His tribe Daws largely refused. He returned to the Prophet ﷺ and said: 'Pray against the Daws.' The Prophet ﷺ raised his hands and said: 'O Allah, guide the Daws and bring them.' He returned to his tribe and spent years patiently inviting. He brought approximately 80 families to Medina — including the household of Abu Hurayra (rank #7), whose mother Tufayl had converted. Without Tufayl, Abu Hurayra may never have been Muslim — and the largest hadith collection in Islam may never have existed. He fought at Khandaq, Khaybar, and all major campaigns. He was martyred at the Battle of Yamama (633 CE) with both eyes gouged out during the fighting — he had dreamed of this and taken it as a sign. His conversion of Abu Hurayra's household may be the highest-leverage individual act of da'wah in Islamic history.",
