    contrib:
      "Abdullah ibn Hudhafa al-Sahmi was selected by the Prophet ﷺ for the most dangerous diplomatic mission of the early Islamic state: carrying the letter of Islam to Khosrow II, the most powerful emperor on earth. Khosrow received the letter and tore it. The Prophet ﷺ said: 'Allah will tear his kingdom.' Within years, Khosrow was assassinated by his own son and the empire unraveled. Years later, during the Byzantine campaigns, Abdullah was captured. The Byzantine Emperor had him brought to his throne and offered him Christianity — with wealth, status, and freedom as incentives. Abdullah refused. The Emperor ordered him to a vat of boiling water with prisoners. He watched others lowered in screaming. When his turn came, he wept. The Emperor, thinking he was breaking, had him brought before him again and asked: 'Why did you weep?' Abdullah said: 'I wept because I have only one soul. I wished I had a hundred souls so that each one could be boiled for Allah.' The Emperor was so stunned he offered him freedom again if he would just kiss his forehead. Abdullah said: 'Only if you free all Muslim prisoners.' He freed every prisoner in exchange for a forehead kiss — a negotiation that saved all of them. He returned to Medina. Umar said: 'It is the right of every Muslim to kiss the forehead of Abdullah ibn Hudhafa.' He narrated 0 hadiths. His entire legacy is his refusal and his negotiation.",
