    contrib:
      "Habib ibn Zayd al-Ansari was the son of Nusayba bint Ka'b (Umm Umara, rank #96) — making him part of Islam's most remarkable fighting family: mother, father, brother, and son all prominent companions. The Prophet ﷺ sent him as an envoy to Musaylimah al-Kadhdhab (the false prophet) in Yamama with a letter calling him to abandon his claim. Musaylimah captured him and brought him before his followers as a demonstration of power. He asked: 'Do you testify that Muhammad is the Messenger of Allah?' Habib said: 'Yes.' He asked: 'Do you testify that I am a messenger of Allah?' Habib said: 'I cannot hear.' Musaylimah cut off a limb. He asked again. Habib repeated: 'Muhammad is the Messenger of Allah. I cannot hear what you say.' Musaylimah cut another limb. This exchange — the same two questions, the same two answers — was repeated for every limb on his body. He did not recant. He was martyred piece by piece. When Nusayba (rank #96) heard how her son had died, she did not weep for grief — she wept from pride. She then fought at the Battle of Yamama against Musaylimah personally, receiving eleven wounds and losing her hand. The son's martyrdom and the mother's revenge became one of Islam's most documented acts of familial dedication to faith.",
