    contrib:
      "Nusayba bint Ka'b al-Ansariyyah had come to Uhud as a water-carrier and field nurse. When the Muslim line broke — Khalid ibn al-Walid's cavalry exploiting the archers' mistake — and the Prophet ﷺ was suddenly exposed, Nusayba did not run. She grabbed whatever she could — sword and shield from fallen fighters — and stood between the Prophet ﷺ and the Qurayshi attackers. The Prophet ﷺ said afterward: 'Wherever I turned at Uhud — right or left — I saw Umm Umara fighting for me.' She received 13 wounds at Uhud. One wound, from Ibn Qami'a, was so deep in her neck that it took a year to heal. She participated in the Pledge of al-Ridwan (the tree pledge at Hudaybiyyah), a Quranic honor: 'Allah was pleased with the believers when they pledged to you under the tree.' She fought at Khaybar, the Conquest of Mecca, Hunayn, and Taif — the only woman documented across all of these engagements. At Yamama, she fought against Musaylimah (whose forces had killed her son Habib, rank #95 in this collection) and lost her right hand. The Prophet ﷺ's assessment covers her legacy entirely: when asked at Uhud who had protected him best, he answered: 'Umm Umara.' Not one of the ten promised paradise. Not one of the great narrators. A woman who had come to bring water.",
