    ur: 'خزیمہ بن ثابتؓ',
    title: 'Dhu al-Shahadatayn (The Man Whose Testimony Equals Two)',
    cat: 'other',
    catLabel: 'Companion',
    rel: 'The Prophet ﷺ ruled that his single testimony was equal to the testimony of two men — a unique honor in Islamic law',
    relType: 'companion',
    born: '~594 CE',
    death: '~657 CE',
    place: 'Medina',
    tribe: 'Aws (Ansar)',
    sig: 'Known as Dhu al-Shahadatayn, with a unique ruling that his single testimony could count as two in specific contexts',
    contrib:
      "Khuzayma ibn Thabit al-Ansari — known as Dhu al-Shahadatayn (Man of Two Testimonies) — received the highest testimonial certification in Islamic law for a single act: witnessing on behalf of the Prophet ﷺ in a transaction he had not personally witnessed. When the Prophet ﷺ purchased a horse and a Bedouin denied the transaction, Khuzayma testified for the Prophet ﷺ. The Prophet ﷺ asked: 'How can you testify for something you did not see?' He said: 'O Messenger of Allah, I testify to greater things than this — I testify that you receive revelation from the sky. How then could I not trust your word about a horse?' The Prophet ﷺ declared: 'Whoever's testimony Khuzayma supports, let it suffice' — making his single testimony equal to two witnesses. This was a permanent ruling, not a one-time exception. His testimony later preserved the last two verses of the Quran: when Zayd ibn Thabit (rank #26) could not find two witnesses for Surah al-Tawba 9:128-129, only Khuzayma could produce them. Those verses — ending the ninth surah — entered the mushaf on his testimony alone. He narrated 38 hadiths. He refused to fight at Siffin until Ali ibn Abi Talib's forces confirmed that Ammar ibn Yasir (rank #27) had been killed by the other side — fulfilling the Prophet's ﷺ prophecy — and then fought and was martyred at Siffin in 37 AH.",
    hadiths: 38,
    battles: ['Battle of Badr', 'Battle of Uhud', 'Battle of Khandaq', 'Battle of Siffin (killed)'],
    burial: 'Siffin, Syria',
    quote: '',
    quoteEn:
      "He said: 'O Messenger of Allah, I testify to the truth of what you say about the heavens — should I hesitate to testify about a horse?' The Prophet ﷺ said: 'Whoever Khuzayma testifies for, that is sufficient.' — establishing his unique legal status.",
    link: 'His testimony was used in the compilation process for the last two verses of Surah al-Tawba (9:128-129), based on the prophetic ruling about his witness status. He was later killed at Siffin while fighting alongside Ali.',
    personality: [
      "Absolute trust in the Prophet ﷺ — 'I believe you about heaven, why not about a horse?'",
      'His logic was flawless and deeply faithful',
      'Fought in every major battle from Badr to Siffin',
      'His unique legal status was crucial for Quranic preservation',
    ],
    legacy:
      'Khuzayma ibn Thabit (Dhu al-Shahadatayn) is remembered for his unique witness ruling and its later relevance in Quran compilation discussions. His principled reasoning in the horse-transaction incident became a classic legal-ethical reference, and he later died at Siffin after taking a deliberate stance tied to prophetic reports.',
    keyEvent:
      "When Zayd ibn Thabit could not find two witnesses for the last two verses of Surah al-Tawba (9:128-129) during the Quran's compilation, only Khuzayma ibn Thabit came forward. The rule was two witnesses. One was insufficient — except that the Prophet ﷺ had permanently ruled that Khuzayma's single testimony equaled two. Zayd accepted. Those two verses — 'There has certainly come to you a Messenger from among yourselves...' — entered the Quran on Khuzayma's solitary testimony. Every Muslim who has recited the end of Surah al-Tawba has recited what Khuzayma preserved.",
