    contrib:
      "Hasan ibn Ali ibn Abi Talib was described by the Prophet ﷺ as 'a sayyid' — a master, a lord — and that 'through him Allah will reconcile two great groups of Muslims.' The reconciliation came in 41 AH: after Ali's assassination, Hasan became Caliph to the Hashimid faction while Muawiyah ibn Abi Sufyan (rank #50) controlled the Syrian army. A catastrophic civil war threatened to destroy the Muslim world. Hasan — despite the pressure of his followers and his army — abdicated the caliphate to Muawiyah voluntarily, in exchange for specific conditions protecting the community. The Prophet's ﷺ prophecy was fulfilled exactly: two groups reconciled. That year — 41 AH — is called in Islamic history 'the Year of Unity' (Aam al-Jama'a). His companions wept and some called it humiliating. He said: 'By Allah, I have done it for the blood of the Muslims.' He spent his remaining years in Medina as a scholar and narrated 13 hadiths. He was famous for his extreme generosity — he divided his entire wealth in half and gave half to the poor twice in his lifetime. He was physically the most similar of all the Prophet's ﷺ grandchildren to the Prophet ﷺ in appearance — ibn Abbas said 'from the waist up he is like the Prophet ﷺ.' He died in 50 AH, aged approximately 46, and was buried in Jannat al-Baqi.",
