    keyEvent:
      "In 41 AH, with 100,000 soldiers on his side and Muawiyah's army facing him, Hasan ibn Ali made the most consequential political decision in early Islamic history: he abdicated. His followers wept, some called it humiliating, one threw his cloak at him. He said: 'By Allah, I have done it for the sake of the Muslim blood.' The Prophet ﷺ had said: 'This son of mine is a sayyid — through him Allah will reconcile two great groups of Muslims.' The Year of Unity (Aam al-Jama'a) followed. The prophecy was fulfilled.",
