    contrib:
      "Husayn ibn Ali ibn Abi Talib's death at Karbala (10 Muharram, 61 AH) is widely regarded as one of the most consequential post-prophetic events in Islamic history. After receiving calls from Kufa to lead opposition to Yazid ibn Muawiyah, he traveled from Mecca with family members and supporters. By Karbala, anticipated support had largely collapsed under political pressure, and his group was encircled by a much larger force. He refused terms requiring allegiance on those conditions and remained with his companions, who also stayed. On Ashura, after prayer, fighting began and he was killed later that day. Narrations about the Prophet's ﷺ special love for Husayn deeply shaped how Muslims remembered the tragedy.",
