    link: "The Prophet ﷺ once interrupted a sermon when Husayn stumbled while walking toward him — he descended the pulpit to pick him up, saying: 'I saw this child stumbling and I could not continue.' Jibril is reported to have told the Prophet ﷺ of Husayn's future martyrdom — the Prophet ﷺ wept and showed companions soil from Karbala.",
    personality: [
      "Inherited the Prophet's ﷺ courage and moral clarity",
      'Chose certain death over submission to what he saw as tyranny',
      'Dignified even in his final moments — refused to beg',
      'His stand at Karbala defined the principle that silence against oppression is not an option',
    ],
    legacy:
      "Husayn ibn Ali's martyrdom at Karbala became a central memory across Muslim traditions, shaping theology, political thought, and Ashura commemoration. The event remained emotionally and morally formative for later generations, especially alongside hadith emphasizing the Prophet's ﷺ love for Husayn.",
    keyEvent:
      "On the morning of Ashura, 61 AH, Husayn ibn Ali prayed Fajr with his 72 companions on the plain of Karbala. He gave each the option to leave under darkness the night before. None left. When Umar ibn Sa'd's army of 30,000 moved toward him, Husayn rode out and addressed them one last time: 'Are you going to kill me — when I am the son of your Prophet's daughter, the grandson of the man you claim to follow? Look at me. Is there anyone among you who does not know who I am?' Some wept. None stood down. He was killed mid-afternoon on 10 Muharram.",
    appearance: '',
    miracles: '',
