    tribe: 'Banu Tamim (freed slave)',
    sig: 'One of the earliest converts to Islam — his slave-master pressed burning iron coals to his bare back until they cooled in his flesh, yet he never renounced his faith',
    contrib:
      "Khabbab ibn al-Aratt al-Tamimi was among the first seven Muslims and the most completely documented example of slave-torture for Islam in the early period. He was a blacksmith — a skilled craftsman enslaved in Mecca — who converted immediately when Islam came and was subsequently tortured by his owner Umm Anmar (also called Siba'a bint al-Aratt) with methods unique to his profession: red-hot coals were placed on his bare back and he was made to lie on them until his body itself extinguished them. He narrated his own torture in specific detail: 'My back still carries these marks.' When the Prophet ﷺ saw his back, he wept and prayed for the persecuted companions. When Khabbab asked: 'Why don't you ask Allah to help us?' the Prophet ﷺ said he was not to say so — and described how previous believers had been sawed in half without abandoning their faith, and that this religion would be completed. Khabbab lived long enough to become wealthy in Kufa after Islam's conquests. He died approximately 37 AH, having seen the reverse of everything he had suffered: from a tortured slave with nothing to a freeholder in a prosperous city. On his deathbed, he wept and said: 'The companions departed without the world taking anything from them. We have remained and found no place for our wealth except the earth.' He was criticizing his own wealth — the man who had been tortured for having no material security was now troubled by having too much.",
    hadiths: 32,
    battles: ['Battle of Badr', 'Battle of Uhud', 'Battle of Khandaq'],
    burial: 'Kufa, Iraq',
    quote: '',
    quoteEn:
      "The Prophet ﷺ visited him when he was ill and found him lying on his back on the ground. He asked about his condition. Khabbab uncovered his back — it was covered with burn marks from coals. He said: 'No one has been tortured for Allah's sake as I have been.' The Prophet ﷺ wept.",
    link: "His was among the most severe torture cases in early Islam. The Prophet ﷺ told the persecuted early Muslims: 'By Allah, this matter (Islam) will be completed until a rider travels from Sanaa to Hadhramawt fearing no one but Allah.' Khabbab's suffering was the price of that prophecy.",
    personality: [
      'Endured burning coal torture without breaking — among the most tortured early Muslims',
      'His back was permanently scarred — he showed it to the Prophet ﷺ personally',
      'Unusually self-aware about the spiritual dangers of worldly success',
      'One of the Sabaq al-Awwalun — the very first Muslims',
    ],
    legacy:
      "Khabbab ibn al-Aratt's deathbed weeping over his own wealth — after severe early persecution — is among the most poignant companion narrations. He started with everything stripped from him and later feared worldly accumulation for himself. He died approximately 37 AH and is buried in Kufa.",
    keyEvent:
      "On his deathbed, Khabbab ibn al-Aratt wept. The companions who came to see him said: 'Why do you weep — you are the companion of the Prophet ﷺ, you were among the first Muslims, you endured torture for Islam. This is your time to rejoice.' He said: 'I weep because the companions departed without the world giving them anything. We have remained — and the only place we have found for our wealth is the earth.' He pointed to houses he had built in Kufa. Then he said: 'I fear that Allah has given us our reward here.' The man who had been tortured for having nothing was troubled by having too much.",
    appearance: '',
    miracles: '',
