    contrib:
      "Rafi' ibn Khadij ibn Rafi' al-Ansari al-Awsi was from the Banu Haritha section of the Aws tribe of Medina. He was so young at the time of Badr that the Prophet ﷺ could not permit him to join the army. At Uhud he presented himself again — the Prophet ﷺ saw that he was tall for his age and permitted him to fight. He participated in all remaining battles and expeditions. He is particularly important as a narrator of hadiths related to agriculture and economics — he narrated the Prophet's ﷺ rulings on sharecropping (muzara'ah), renting of land, and transactions. His 78 narrated hadiths include rulings that formed the basis of Islamic agricultural law (fiqh al-zira'ah). He also narrated hadiths on the prohibition of certain types of rentals and the conditions for permissible farming arrangements. The jurists of Medina relied heavily on his narrations for economic fiqh. He lived to an old age in Medina, dying around 693 CE, and was among the last of the Ansar companions to pass away.",
